 hr:=exists(select 1 from public.company_module_access where company_id=c and module_key='hr' and enabled) or (hr_private.active_member(c,u) and bolig_private.hr_included(c,u));
 usable_hr:=hr_private.has_module_access(c,u) and (admin or exists(select 1 from hr_private.firms where company_id=c and enabled));
 return jsonb_build_object('company_id',c,'user_id',u,'company_name',(select display_name from public.sales_company_scopes where id=c),
  'personal_page',ks or hr or exists(select 1 from bolig_private.attendance_people a join bolig_private.roots r on r.id=a.root_id join bolig_private.attendance_states s on s.root_id=r.id join bolig_private.firms f on f.company_id=r.company_id where a.user_id=u and a.enabled and r.company_id=c and not r.archived and s.enabled and f.enabled) or exists(select 1 from progress_private.assignments x join public.projects pr on pr.id=x.project_id where x.user_id=u and pr.company_scope_id=c and not coalesce(pr.locked,false)),'company_kshms',ks,'company_hr',hr,
  'hr_management',usable_hr and (admin or exists(select 1 from hr_private.employees e
   where e.company_id=c and e.leader_id=u and hr_private.active_member(c,e.user_id))), 'content_enabled',false);
end$function$

